#!/usr/bin/env python3
"""Export the Python-owned finance research contract, or check generated files for drift."""
import argparse
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
from lib.wealth.research import RentVsBuyResult, ResearchSnapshot  # noqa: E402


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    outputs = {}
    for name, model in [("finance-research", ResearchSnapshot), ("finance-research-whatif", RentVsBuyResult)]:
        schema = json.dumps(model.model_json_schema(mode="serialization"), indent=2) + "\n"
        result = subprocess.run([str(ROOT / "web/node_modules/.bin/json2ts"), "--no-additionalProperties"], input=schema, text=True, capture_output=True, check=True, cwd=ROOT / "web")
        outputs.update({ROOT / f"web/lib/{name}.schema.json": schema, ROOT / f"web/lib/{name}.gen.ts": "// Generated by scripts/export_finance_research_schema.py. Do not edit.\n" + result.stdout})
    for file, content in outputs.items():
        if args.check:
            if not file.exists() or file.read_text() != content:
                print("[Status: Critical] Regenerate with .venv/bin/python3 scripts/export_finance_research_schema.py")
                return 1
        else:
            file.write_text(content)
    print("[Status: OK] Finance research contract is current")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
